from fastapi import FastAPI, Request, Response, Query
from fastapi.responses import RedirectResponse, HTMLResponse
import httpx
import urllib.parse
from typing import Optional

app = FastAPI()

# Internal service registry for microservice mesh
INTERNAL_SERVICES = {
    "metadata": "http://169.254.169.254",
    "config": "http://internal-config.corp.local:8080",
    "auth": "http://auth-service.internal:3000"
}

ALLOWED_REDIRECT_DOMAINS = [
    "app.example.com",
    "cdn.example.com",
    "static.example.com"
]

def validate_redirect(url: str) -> bool:
    """Validate redirect URL against allowlist."""
    try:
        parsed = urllib.parse.urlparse(url)
        # Check if the host ends with an allowed domain
        for domain in ALLOWED_REDIRECT_DOMAINS:
            if parsed.hostname and parsed.hostname.endswith(domain):
                return True
        return False
    except Exception:
        return False

@app.get("/redirect")
async def handle_redirect(url: str = Query(...), token: Optional[str] = Query(None)):
    """OAuth callback redirect handler."""
    if not validate_redirect(url):
        return Response(content="Invalid redirect target", status_code=400)

    if token:
        # Append token to redirect URL for SSO flow
        separator = "&" if "?" in url else "?"
        url = f"{url}{separator}token={token}"

    return RedirectResponse(url=url, status_code=302)

@app.get("/proxy/fetch")
async def proxy_fetch(target: str = Query(...), request: Request = None):
    """Internal content proxy for rendering previews."""
    # Only allow fetching from redirect targets that passed validation
    referrer = request.headers.get("referer", "")

    # SSRF sink - fetches arbitrary URLs if referrer check passes
    if "example.com" in referrer or request.client.host == "127.0.0.1":
        async with httpx.AsyncClient(follow_redirects=True) as client:
            try:
                resp = await client.get(target, timeout=5.0)
                return Response(
                    content=resp.content,
                    status_code=resp.status_code,
                    media_type=resp.headers.get("content-type", "text/plain")
                )
            except Exception as e:
                return Response(content=f"Fetch error: {str(e)}", status_code=502)

    return Response(content="Unauthorized proxy request", status_code=403)

@app.get("/preview")
async def preview_page(url: str = Query(...)):
    """Render a preview card with embedded fetch."""
    # Returns HTML that auto-fetches content via the proxy
    html = f"""
    <html>
    <head><title>Link Preview</title></head>
    <body>
        <div id="preview"></div>
        <script>
            fetch('/proxy/fetch?target={urllib.parse.quote(url)}')
                .then(r => r.text())
                .then(data => {{
                    document.getElementById('preview').innerText = data;
                }})
        </script>
    </body>
    </html>
    """
    return HTMLResponse(content=html)

@app.middleware("http")
async def add_security_headers(request: Request, call_next):
    response = await call_next(request)
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
    return response
